mapper.select:
SELECT DISTINCT maker_code AS makerCode, model_group_code AS modelGroupCode, model_group_name AS modelGroupName FROM cz_model_group
AND maker_code = #{maker}
ORDER BY class_order, model_group_name

SELECT DISTINCT maker_code AS makerCode, model_group_code AS modelGroupCode, model_code AS modelCode, model_name AS modelName FROM cz_model
AND maker_code = #{maker}
AND model_group_code = #{modelGroup}
ORDER BY car_order, model_name

SELECT DISTINCT maker_code AS makerCode, model_group_code AS modelGroupCode, model_code AS modelCode, trim_code AS trimCode, trim_name AS trimName FROM cz_trim
AND maker_code = #{maker}
AND model_group_code = #{modelGroup}
AND model_code = #{model}
ORDER BY model_order, trim_name

SELECT DISTINCT
    maker_code AS makerCode,
    model_group_code AS modelGroupCode,
    model_code AS modelCode,
    trim_code AS trimCode,
    grade_code AS gradeCode,
    grade_name AS gradeName
FROM cz_grade


        AND maker_code = #{maker}


        AND model_group_code = #{modelGroup}


        AND model_code = #{model}


        AND trim_code = #{trim}


ORDER BY grade_order, grade_name
